// Generated by Claude/specs/courses-tools/sync-hr.js from Claude/specs/lxd-course-hr-pilot/out-rounds/hr-pilot-block.js. Do not hand-edit.
(function(E){ const x = E["hr-m8"] = E["hr-m8"] || {units:{}}; x.units["hr-8-1"] = {"explain":{"id":"c-hr-8-1-e","course":"hr","unit":"hr-8-1","type":"explain","level":"B1","title":{"en":"The disciplinary process","tr":"Disiplin süreci","fa":"روند انضباطی"},"objective":{"en":"After this lesson, you can invite an employee to a disciplinary meeting in writing and run the meeting fairly.","tr":"Bu dersin sonunda bir çalışanı yazılı olarak disiplin görüşmesine davet edip görüşmeyi adil biçimde yürütebileceksin.","fa":"بعد از این درس می‌توانی کارمندی را کتبی به جلسه‌ی انضباطی دعوت کنی و جلسه را منصفانه پیش ببری."},"hook":{"en":"Decide last, after the facts and the meeting. A decision made earlier makes the process unfair. Omar wants Yusuf gone today. Leyla knows a fair process starts with the facts, not the decision.","tr":"En son, olgulardan ve görüşmeden sonra karar ver. Daha önce verilen bir karar süreci haksız yapar. Omar, Yusuf’un bugün gitmesini istiyor. Leyla adil bir sürecin kararla değil, olgularla başladığını biliyor.","fa":"آخر از همه، بعد از واقعیت‌ها و جلسه تصمیم بگیر. تصمیم زودتر از آن، روند را ناعادلانه می‌کند. عمر می‌خواهد یوسف همین امروز برود. لیلا می‌داند روند منصفانه با واقعیت‌ها شروع می‌شود، نه با تصمیم."},"before":{"en":"Write the key lines of an invitation to a disciplinary meeting: the problem, the facts, the right to bring a colleague, and that nothing is decided yet.","tr":"Bir disiplin toplantısı davetinin temel satırlarını yaz: sorun, olgular, bir iş arkadaşı getirme hakkı ve henüz hiçbir şeye karar verilmediği.","fa":"سطرهای اصلی دعوت‌نامه‌ی یک جلسه‌ی انضباطی را بنویس: مشکل، واقعیت‌ها، حق آوردن یک همکار و اینکه هنوز تصمیمی گرفته نشده."},"rounds":[[1,4],[2,3]],"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"4"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"5"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"5"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Decide last","tr":"En son karar ver","fa":"آخر از همه تصمیم بگیر"},"body":{"en":"If you have already decided, the meeting has no point. So get the facts, share them in writing and hear the person's side. Only then decide.","tr":"Kararını çoktan verdiysen görüşmenin bir anlamı kalmaz. Bu yüzden olguları topla, yazılı olarak paylaş ve kişinin kendi tarafını dinle. Ancak ondan sonra karar ver.","fa":"اگر از قبل تصمیم گرفته باشی، جلسه بی‌معنی است. پس واقعیت‌ها را جمع کن، کتبی در میان بگذار و حرف آن شخص را بشنو. فقط بعد از آن تصمیم بگیر."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Facts without judging: the records show, it appears, according to","tr":"Yargılamadan olgular: the records show, it appears, according to","fa":"واقعیت بدون قضاوت: the records show، it appears، according to"},"steps":[{"en":"A fact from a document: The records show that + sentence.","tr":"Belgeden bir olgu: The records show that + cümle.","fa":"برای واقعیتی از یک سند، The records show that و یک جمله می‌آید.","ex":"The records show that the check was not done on 4 May."},{"en":"Something not yet proved: It appears that + sentence.","tr":"Henüz kanıtlanmamış bir şey: It appears that + cümle.","fa":"برای چیزی که هنوز ثابت نشده، It appears that و یک جمله می‌آید.","ex":"It appears that the brake light was not checked."},{"en":"What a person said: According to + person, + sentence.","tr":"Birinin söylediği: According to + kişi, + cümle.","fa":"برای حرف یک نفر، According to و اسم آن شخص می‌آید و بعد جمله.","ex":"According to the yard supervisor, the van left at 6:10."}],"table":{"headers":{"en":["Judging (avoid)","Neutral (use)"],"tr":["Yargılayan (kaçın)","Tarafsız (kullan)"],"fa":["قضاوتی (نگو)","بی‌طرف (بگو)"]},"rows":[["You ignored the safety check.","The records show that the safety check was not completed."],["You are careless.","It appears that the brake light was not checked."],["Everyone saw you leave early.","According to the yard supervisor, the van left at 6:10."]]},"tip":{"en":"After it appears that, write a full sentence with its own verb: it appears that the check was missed.","tr":"It appears that’ten sonra kendi fiili olan tam bir cümle yaz: it appears that the check was missed.","fa":"بعد از it appears that یک جمله‌ی کامل با فعل خودش بنویس: it appears that the check was missed."},"wrong":"It appears that the check missed.","right":"It appears that the check was missed."},{"eyebrow":{"en":"Key phrases","tr":"Anahtar ifadeler","fa":"عبارت‌های کلیدی"},"head":{"en":"Phrases for this task","tr":"Bu görev için ifadeler","fa":"عبارت‌های این کار"},"phrases":[{"phrase":"investigation","meaning":{"en":"Collecting the facts before any decision.","tr":"Herhangi bir karardan önce olguları toplamak.","fa":"جمع کردن واقعیت‌ها قبل از هر تصمیمی."}},{"phrase":"The purpose of the meeting is to...","meaning":{"en":"Says why the meeting is held.","tr":"Toplantının neden yapıldığını söyler.","fa":"می‌گوید جلسه برای چیست."}},{"phrase":"You may bring a colleague with you.","meaning":{"en":"Gives the right to be accompanied.","tr":"Yanında birini getirme hakkını verir.","fa":"حق همراه داشتن را می‌گوید."}},{"phrase":"No decision has been made yet.","meaning":{"en":"Shows the outcome is still open.","tr":"Sonucun henüz belli olmadığını gösterir.","fa":"نشان می‌دهد نتیجه هنوز باز است."}},{"phrase":"first written warning","meaning":{"en":"A formal warning that stays on file for a set time.","tr":"Belirli bir süre dosyada kalan resmî uyarı.","fa":"اخطار کتبی رسمی که مدت مشخصی در پرونده می‌ماند."}}]},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Investigate, invite, meet, decide, appeal","tr":"Araştır, davet et, görüş, karar ver, itiraz","fa":"بررسی، دعوت، جلسه، تصمیم، اعتراض"},"body":{"en":"The UK Acas Code sets the order: investigate first, tell the employee the problem in writing, hold a meeting where they can bring a colleague, then give the decision in writing with the right to appeal. UAE law also says the penalty and its reason must be given in writing. Nobody decides the outcome before the meeting.","tr":"Birleşik Krallık’taki Acas Kuralları sırayı belirler: önce araştır, sorunu çalışana yazılı bildir, yanında bir meslektaşını getirebileceği bir görüşme yap, sonra kararı itiraz hakkıyla birlikte yazılı ver. BAE yasası da cezanın ve gerekçesinin yazılı bildirilmesini ister. Sonuca görüşmeden önce kimse karar vermez.","fa":"آیین‌نامه‌ی Acas در بریتانیا ترتیب را مشخص می‌کند: اول بررسی کن، مشکل را کتبی به کارمند بگو، جلسه‌ای بگذار که بتواند یک همکار را همراه بیاورد و بعد تصمیم را همراه با حق اعتراض کتبی اعلام کن. قانون امارات هم می‌گوید جریمه و دلیلش باید کتبی اعلام شود. هیچ‌کس قبل از جلسه درباره‌ی نتیجه تصمیم نمی‌گیرد."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From weak to strong","tr":"Zayıftan güçlüye","fa":"از تصمیم زودهنگام تا جلسه‌ی منصفانه"},"text":"Facts: The problem: a missing check. A colleague may attend. Nothing is decided yet.","item":"We have decided to dismiss you. Please come to a meeting.","why":{"en":"Weak: the decision comes first. Strong: facts, a right, an open outcome.","tr":"Zayıf: karar önce geliyor. Güçlü: olgular, bir hak, açık bir sonuç.","fa":"در نسخه‌ی اول تصمیم زودتر از همه‌چیز آمده است. نسخه‌ی دوم واقعیت‌ها و یک حق را می‌گوید و نتیجه هنوز باز است."},"answer":"The purpose of the meeting is to discuss the missing check. You may bring a colleague. No decision has been made yet.","cut":["We have decided to dismiss you."],"cutHint":{"en":"Tap what makes the meeting pointless.","tr":"Toplantıyı anlamsız kılan cümleye dokun.","fa":"روی جمله‌ای بزن که جلسه را بی‌فایده می‌کند."}},"quick":{"prompt":"When do you decide the outcome of a disciplinary case?","options":["After the meeting, once you have heard their side","Before the meeting, so it is quick","When you send the invitation"],"correct":0,"why":{"en":"After you have heard their side: if you have already decided, the meeting has no point.","tr":"Onun tarafını dinledikten sonra: Kararı önceden verdiysen toplantının hiçbir anlamı kalmaz.","fa":"بعد از اینکه حرف او را شنیدی: اگر از قبل تصمیمت را گرفته باشی، جلسه هیچ فایده‌ای ندارد."},"point":1},"remember":{"en":"Facts with a source, no judgement, no decision before the meeting. Result of this lesson: you can invite someone to a fair meeting. You also have the invitation letter.","tr":"Kaynağıyla olgular, yargı yok, görüşmeden önce karar yok. Bu dersin sonucu: birini adil bir görüşmeye davet edebilirsin ve elinde davet mektubu olur.","fa":"واقعیت را با منبعش بگو، بدون قضاوت و بدون تصمیم قبل از جلسه. حالا می‌توانی کسی را به جلسه‌ای منصفانه دعوت کنی. نامه‌ی دعوت هم آماده است."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Formal arrangements: is to be held, you are to...","tr":"Resmî düzenlemeler: is to be held, you are to...","fa":"قرارهای رسمی: is to be held، you are to..."},"steps":[{"en":"A formal arrangement: be + to + verb.","tr":"Resmî bir düzenleme: be + to + fiil.","fa":"برای یک قرار رسمی، be و to و فعل می‌آید.","ex":"The meeting is to take place on 12 May at 10:00."},{"en":"The same in the passive: is to be + past participle.","tr":"Aynısı edilgen çatıda: is to be + past participle.","fa":"در حالت مجهول می‌شود is to be و اسم مفعول.","ex":"The meeting is to be held in Room 2."},{"en":"A formal instruction: You are to + verb.","tr":"Resmî bir talimat: You are to + fiil.","fa":"برای یک دستور رسمی، You are to و فعل می‌آید.","ex":"You are to bring any documents you wish to use."}],"body":{"en":"B2 track: in your invitation letter, use is to be held once.","tr":"B2 yolu: davet mektubunda is to be held yapısını bir kez kullan.","fa":"مسیر B2: در نامه‌ی دعوتت یک بار is to be held را به کار ببر."}},"source":{"en":"Based on the Acas Code of Practice and Acas guidance on investigations; written-penalty rule from UAE law.","tr":"Acas uygulama kurallarına ve Acas’ın soruşturma rehberine dayanır; yazılı ceza kuralı BAE yasasından alınmıştır.","fa":"بر پایه‌ی آیین‌نامه‌ی Acas و راهنمای Acas درباره‌ی بررسی؛ قاعده‌ی کتبی بودن جریمه از قانون امارات."}},"story":{"id":"c-hr-8-1-s","course":"hr","unit":"hr-8-1","level":"B1","genre":"Workplace","title":{"en":"Before the Decision","tr":"Karardan Önce","fa":"قبل از تصمیم"},"text":"On Monday morning a customer called about a van with a broken brake light. Omar checked the log. The van was Yusuf's, and the safety check had been signed as done.\n\n\"Twice in one week,\" Omar said. \"I want him out today.\"\n\n\"Not today,\" Leyla said. \"First we find out what happened.\"\n\nShe spent the afternoon on the facts. The records showed that the safety check was not completed on 4 and 6 May: the tablet app had no entries, but the paper log had Yusuf's signature. According to the yard supervisor, the van left at 6:10 on both days, ten minutes after Yusuf arrived. A full check takes fifteen.\n\nThat evening Leyla wrote to Yusuf. The letter said what the problem was and attached the records. \"It appears that the check was signed but not carried out,\" it said. It gave the time of the meeting, said he could bring a colleague, and said that no decision had been made yet.\n\nYusuf came on Thursday with Hasan beside him. He did not argue about the dates. \"The tablet kept freezing,\" he said. \"So I signed the paper and went. The early customers complain if we are late.\"\n\n\"Did anyone tell you to skip the check?\" Leyla asked.\n\nYusuf looked at Hasan. \"Nobody said it. But everybody knows the first drops matter most.\"\n\nAfter the meeting Leyla made her decision: a first written warning, kept on file for six months, and a new rule for the whole yard. No van leaves before its check is done, and a frozen tablet means a paper check, not no check.\n\nOmar read the letter. \"Only a warning?\"\n\n\"For him,\" Leyla said. \"And a rule for everyone. The problem was bigger than Yusuf.\"","vocab":[{"word":"brake light","en":"The red light at the back of a vehicle that shows it is stopping.","tr":"fren lambası","fa":"چراغ ترمز"},{"word":"log","en":"A written record of what was done and when.","tr":"kayıt defteri","fa":"دفتر ثبت"},{"word":"carry out","en":"To do a task.","tr":"yerine getirmek, yapmak","fa":"انجام دادن"},{"word":"on file","en":"Kept in a person's official record.","tr":"dosyada (kayıtlı)","fa":"در پرونده"}],"quiz":[{"prompt":"Why does Leyla not agree to dismiss Yusuf on Monday?","options":["She wants to find out the facts first","Yusuf is her friend","Omar is not his manager"],"correct":0},{"prompt":"Which sentence states a fact without judging?","options":["Yusuf is lazy and careless.","The records showed that the safety check was not completed on 4 and 6 May.","Everybody knows he skips checks."],"correct":1},{"prompt":"What did Yusuf say about the checks?","options":["The tablet kept freezing, so he signed the paper and left","He forgot about them","Hasan told him to skip them"],"correct":0},{"prompt":"How might Yusuf feel with Hasan beside him in the meeting?","options":["Less alone, because someone he trusts is there","Angry with Hasan","Sure that he will lose his job"],"correct":0}],"notice":{"en":"Notice how Leyla's letter gives each fact with its source.","tr":"Leyla’nın mektubunun her olguyu kaynağıyla birlikte verdiğine dikkat et.","fa":"دقت کن نامه‌ی لیلا هر واقعیت را همراه با منبعش می‌گوید."},"bridge":{"en":"Next: run the meeting with Yusuf yourself.","tr":"Sırada: Yusuf’la görüşmeyi sen yönet.","fa":"قدم بعد: جلسه با یوسف را خودت اداره کن."}},"speaking":{"id":"hr-8-1","course":"hr","unit":"hr-8-1","rounds":[90,60],"topic":{"en":"Opening a Disciplinary Meeting","tr":"Bir Disiplin Görüşmesini Açmak","fa":"شروع یک جلسه‌ی انضباطی"},"warmup":{"en":"Have you ever had to explain a mistake at work or school? What made it feel fair or unfair?","tr":"Hiç iş yerinde ya da okulda bir hatayı açıklamak zorunda kaldın mı? Bunu adil ya da adaletsiz hissettiren neydi?","fa":"تا حالا مجبور شده‌ای در محل کار یا مدرسه اشتباهی را توضیح بدهی؟ چه چیزی باعث شد منصفانه یا ناعادلانه به نظر برسد؟"},"questions":[{"en":"Welcome the employee and their companion, and say the purpose of the meeting.","tr":"Çalışanı ve yanındaki kişiyi karşıla, görüşmenin amacını söyle.","fa":"به کارمند و همراهش خوشامد بگو و هدف جلسه را بگو."},{"en":"Say that no decision has been made yet.","tr":"Henüz bir karar verilmediğini söyle.","fa":"بگو هنوز تصمیمی گرفته نشده."},{"en":"State the problem with facts and a source for each one.","tr":"Sorunu olgularla ve her birinin kaynağıyla anlat.","fa":"مشکل را با واقعیت‌ها و منبع هر کدام بگو."},{"en":"Ask for the employee's side and say what happens next.","tr":"Çalışanın anlatacaklarını sor ve sonra ne olacağını söyle.","fa":"نظر کارمند را بپرس و بگو بعدش چه می‌شود."}],"followups":[{"en":"Say it in 90 seconds, then in 60. Keep the facts and the next step.","tr":"Önce 90, sonra 60 saniyede söyle. Olguları ve sonraki adımı koru.","fa":"یک بار در ۹۰ ثانیه و بعد در ۶۰ ثانیه بگو. واقعیت‌ها و قدم بعدی را نگه دار."},{"en":"Now say how a disciplinary meeting starts at your company, or how you think it should.","tr":"Şimdi şirketinde disiplin görüşmesinin nasıl başladığını ya da sence nasıl başlaması gerektiğini söyle.","fa":"حالا بگو جلسه‌ی انضباطی در شرکتت چطور شروع می‌شود یا به نظرت باید چطور شروع شود."}],"expressions":[{"phrase":"The purpose of the meeting is to hear your side.","meaning":{"en":"States the purpose.","tr":"Amacı söyler.","fa":"هدف را می‌گوید."}},{"phrase":"The records show that...","meaning":{"en":"Gives a fact from a document.","tr":"Bir belgeden olgu verir.","fa":"واقعیتی از یک سند را می‌گوید."}},{"phrase":"You'll have my decision in writing by Monday.","meaning":{"en":"Says what happens next.","tr":"Sonra ne olacağını söyler.","fa":"می‌گوید بعدش چه می‌شود."}}],"culture":{"en":"In many workplaces in Turkey, Iran and the Persian Gulf, a disciplinary talk can mean a loss of face, so people may stay silent or deny everything. A private room, a calm voice and clear facts make it easier to speak. In the UK, the companion can help the employee put their case, but cannot answer questions for them.","tr":"Türkiye’de, İran’da ve Basra Körfezi’nde birçok iş yerinde disiplin görüşmesi itibar kaybı gibi hissedilebilir; bu yüzden insanlar susabilir ya da her şeyi inkâr edebilir. Özel bir oda, sakin bir ses ve net olgular konuşmayı kolaylaştırır. Birleşik Krallık’ta yanındaki kişi çalışanın kendini anlatmasına yardım edebilir ama onun yerine soruları cevaplayamaz.","fa":"در خیلی از محیط‌های کاری در ترکیه، ایران و کشورهای خلیج فارس، جلسه‌ی انضباطی می‌تواند مثل از دست دادن آبرو باشد؛ برای همین ممکن است آدم‌ها ساکت بمانند یا همه‌چیز را انکار کنند. اتاق خصوصی، صدای آرام و واقعیت‌های روشن حرف زدن را آسان‌تر می‌کند. در بریتانیا همراه می‌تواند به کارمند کمک کند حرفش را بزند، اما نمی‌تواند به جای او به سؤال‌ها جواب بدهد."},"model":"Good morning, Yusuf, and thank you for coming, Hasan. The purpose of the meeting is to hear your side, and no decision has been made yet. The records show that the safety check was not completed on 4 and 6 May, and according to the yard supervisor, the van left at 6:10. Can you tell me what happened? You'll have my decision in writing by Monday.","selfCheck":[{"en":"I welcomed both people and said the purpose.","tr":"İki kişiyi de karşıladım ve amacı söyledim.","fa":"به هر دو نفر خوشامد گفتم و هدف را گفتم."},{"en":"I said that no decision has been made.","tr":"Henüz karar verilmediğini söyledim.","fa":"گفتم هنوز تصمیمی گرفته نشده."},{"en":"I gave facts with a source, without judging.","tr":"Olguları kaynağıyla, yargılamadan verdim.","fa":"واقعیت‌ها را با منبع و بدون قضاوت گفتم."},{"en":"I asked for their side and said what happens next.","tr":"Onun anlatacaklarını sordum ve sonra ne olacağını söyledim.","fa":"نظرش را پرسیدم و گفتم بعدش چه می‌شود."}]},"branch":{"id":"c-hr-8-1-b","course":"hr","unit":"hr-8-1","type":"branch","title":{"en":"The Disciplinary Meeting","tr":"Disiplin Görüşmesi","fa":"جلسه‌ی انضباطی"},"setting":{"en":"Room 2, Thursday 10:00. You are Leyla. Yusuf is here with Hasan as his companion. Choose what to say. If a choice goes badly, you will see what happens and can try again.","tr":"2 numaralı oda, perşembe saat 10:00. Sen Leyla’sın. Yusuf, yanında Hasan’la geldi. Ne söyleyeceğini seç. Bir seçim kötü giderse ne olduğunu görür ve yeniden deneyebilirsin.","fa":"اتاق ۲، پنجشنبه ساعت ۱۰. تو لیلا هستی. یوسف با حسن به‌عنوان همراه آمده. انتخاب کن چه بگویی. اگر انتخابی خوب پیش نرود، نتیجه‌اش را می‌بینی و می‌توانی دوباره امتحان کنی."},"start":"n1","nodes":{"n1":{"speaker":"Yusuf","line":"Hasan's here with me. Is that okay?","choices":[{"text":"Yes, of course. Hasan can help you put your side, but you'll answer my questions yourself. Today is about hearing your side; no decision has been made yet.","tone":"good","next":"n2","reply":"Okay. Thank you.","feedback":{"en":"You welcome the companion, explain his role and say that nothing is decided.","tr":"Yanındaki kişiyi karşılıyor, rolünü açıklıyor ve hiçbir şeyin karara bağlanmadığını söylüyorsun.","fa":"به همراهش خوشامد می‌گویی، نقشش را توضیح می‌دهی و می‌گویی هنوز تصمیمی گرفته نشده."}},{"text":"This won't take long. We both know what happened.","tone":"poor","next":"n1","reply":"(Yusuf goes quiet.) Then why am I here?","feedback":{"en":"This sounds as if the decision is already made. Say the meeting is there to hear his side.","tr":"Bu, karar çoktan verilmiş gibi duyuluyor. Görüşmenin onun anlatacaklarını dinlemek için olduğunu söyle.","fa":"این‌طوری به نظر می‌رسد که تصمیم از قبل گرفته شده. بگو جلسه برای شنیدن حرف‌های اوست."}},{"text":"Fine. Let's start.","tone":"ok","next":"n2","reply":"Okay...","feedback":{"en":"Correct, but cold. Say what the meeting is for.","tr":"Doğru ama soğuk. Görüşmenin ne için olduğunu söyle.","fa":"درست است ولی سرد. بگو جلسه برای چیست."}}]},"n2":{"speaker":"Yusuf","line":"So what exactly is the problem?","choices":[{"text":"The records show that the safety check was not completed on 4 and 6 May, but the paper log was signed. According to the yard supervisor, the van left ten minutes after you arrived. Can you tell me what happened?","tone":"good","next":"n3","reply":"The tablet kept freezing. So I signed the paper and went.","feedback":{"en":"Facts, a source for each one, then an open question.","tr":"Olgular, her birinin kaynağı ve ardından açık bir soru.","fa":"واقعیت‌ها، منبع هر کدام و بعد یک سؤال باز."}},{"text":"You lied on the log, Yusuf.","tone":"poor","next":"n2","reply":"(Hasan leans forward.) That's a big word. Can we see the records?","feedback":{"en":"Lied is a judgement. Give the facts the records show.","tr":"Lied bir yargıdır. Kayıtların gösterdiği olguları ver.","fa":"lied یک قضاوت است. واقعیت‌هایی را بگو که سوابق نشان می‌دهند."}},{"text":"There's a problem with your checks.","tone":"ok","next":"n2","reply":"What problem? Which checks?","feedback":{"en":"Too vague: he cannot answer until you give the dates and the records.","tr":"Çok belirsiz: tarihleri ve kayıtları vermeden cevap veremez.","fa":"خیلی مبهم است: تا تاریخ‌ها و سوابق را نگویی نمی‌تواند جواب بدهد."}}]},"n3":{"speaker":"Yusuf","line":"The early customers complain if we're late. Nobody told me to skip it, but everyone does.","choices":[{"text":"Thank you for being honest. I'll look at everything you've said and give you my decision in writing by Monday, with how to appeal.","tone":"good","next":"end","reply":"Okay. That's fair.","feedback":{"en":"No decision in the room; you say when and how he will hear it.","tr":"Odada karar yok; kararı ne zaman ve nasıl duyacağını söylüyorsun.","fa":"در جلسه تصمیم نمی‌گیری؛ می‌گویی کی و چطور نتیجه را می‌شنود."}},{"text":"That's no excuse. You're getting a final warning.","tone":"poor","next":"n3","reply":"(Hasan) Are you deciding now, before you've checked what he said?","feedback":{"en":"Deciding in the room ignores what you just heard. End the meeting and decide afterwards.","tr":"Odada karar vermek az önce duyduklarını yok saymak olur. Görüşmeyi bitir ve kararı sonra ver.","fa":"تصمیم گرفتن در همان جلسه یعنی حرفی را که شنیدی نادیده بگیری. جلسه را تمام کن و بعد تصمیم بگیر."}},{"text":"Okay. We'll let you know.","tone":"ok","next":"end","reply":"When?","feedback":{"en":"It ends the meeting, but gives no date and says nothing about an appeal.","tr":"Görüşmeyi bitiriyor ama tarih vermiyor ve itirazdan hiç bahsetmiyor.","fa":"جلسه را تمام می‌کند، ولی تاریخی نمی‌دهد و چیزی درباره‌ی اعتراض نمی‌گوید."}}]},"end":{"end":true,"outcome":{"en":"Yusuf leaves knowing what happens next. Before she decides, Leyla checks the tablet problem with the yard.","tr":"Yusuf sonra ne olacağını bilerek çıkıyor. Leyla karar vermeden önce tablet sorununu sahayla birlikte kontrol ediyor.","fa":"یوسف با دانستن قدم بعدی بیرون می‌رود. لیلا قبل از تصمیم، مشکل تبلت را با محوطه‌ی بارگیری بررسی می‌کند."}}}},"writing":{"id":"c-hr-8-1-w","course":"hr","unit":"hr-8-1","type":"writing","title":{"en":"The invitation letter","tr":"Davet mektubu","fa":"نامه‌ی دعوت"},"difficulty":"hard","prompt":{"en":"Write the letter inviting Yusuf to a disciplinary meeting (70-100 words): the problem with facts, the documents attached, the date, time and place, his right to bring a colleague, that no decision has been made, and the possible outcome.","tr":"Yusuf’u disiplin görüşmesine davet eden mektubu yaz (70-100 kelime): olgularla sorun, ekteki belgeler, tarih, saat ve yer, yanında bir meslektaşını getirme hakkı, henüz karar verilmediği ve olası sonuç.","fa":"نامه‌ی دعوت یوسف به جلسه‌ی انضباطی را بنویس (۷۰ تا ۱۰۰ کلمه): مشکل با واقعیت‌ها، مدارک پیوست، تاریخ و ساعت و مکان، حق اینکه یک همکار را همراه بیاورد، اینکه هنوز تصمیمی گرفته نشده و نتیجه‌ی احتمالی."},"model":"Dear Yusuf, I am writing to invite you to a disciplinary meeting on Thursday 8 May at 10:00 in Room 2. The purpose of the meeting is to discuss the vehicle safety checks on 4 and 6 May. The records show that the checks were not completed, although the paper log was signed. Please find the records attached. You may bring a colleague with you. No decision has been made yet, and you will have the chance to explain what happened. A possible outcome is a written warning. Kind regards, Leyla Karimi, HR Specialist","frame":"Dear ___, I am writing to invite you to a disciplinary meeting on ___ at ___ in ___. The purpose of the meeting is to discuss ___. The records show that ___. Please find ___ attached. You may bring ___ with you. No decision has been made yet, and ___. A possible outcome is ___. Kind regards, ___","words":[{"word":"the records show"},{"word":"purpose"},{"word":"colleague"}],"minWords":70,"minSentences":6,"rubric":["Task done: problem, facts, documents, date and place, colleague, no decision yet, possible outcome","Organised: purpose first, then facts, then arrangements and rights","Language: neutral fact phrases (the records show, according to)","Tone: formal, calm and fair"],"rubricI18n":{"tr":["Görev: sorun, olgular, belgeler, tarih ve yer, meslektaş, henüz karar yok, olası sonuç","Düzen: önce amaç, sonra olgular, sonra düzenlemeler ve haklar","Dil: tarafsız olgu ifadeleri (the records show, according to)","Üslup: resmî, sakin ve adil"],"fa":["کامل بودن کار: مشکل، واقعیت‌ها، مدارک، تاریخ و مکان، همکار، هنوز بدون تصمیم، نتیجه‌ی احتمالی","نظم: اول هدف، بعد واقعیت‌ها، بعد ترتیبات و حقوق","زبان: عبارت‌های بی‌طرف برای واقعیت (the records show، according to)","لحن: رسمی، آرام و منصفانه"]},"portfolio":null,"parts":[{"t":{"en":"The meeting: date, time and place","tr":"Toplantı: tarih, saat ve yer","fa":"جلسه: تاریخ، ساعت و مکان"},"find":["meeting on","room","thursday"],"sample":"Thursday 8 May, 10:00, Room 2"},{"t":{"en":"The problem, with facts","tr":"Olgularıyla birlikte sorun","fa":"مشکل، همراه با واقعیت‌ها"},"find":["purpose of the meeting","the records show"],"sample":"safety checks on 4 and 6 May not done; the log was signed"},{"t":{"en":"The documents","tr":"Belgeler","fa":"مدارک"},"find":["attached","records"],"sample":"the records, attached"},{"t":{"en":"His right to bring a colleague","tr":"Bir iş arkadaşı getirme hakkı","fa":"حقش برای آوردن یک همکار"},"find":["bring a colleague","colleague"],"sample":"he may bring a colleague"},{"t":{"en":"No decision yet, and the possible outcome","tr":"Henüz karar yok ve olası sonuç","fa":"هنوز تصمیمی نیست و نتیجه‌ی احتمالی"},"find":["no decision","possible outcome"],"sample":"nothing decided; a possible written warning"}]},"perspective":{"id":"c-hr-8-1-p","course":"hr","unit":"hr-8-1","type":"perspective","title":{"en":"Through Yusuf’s eyes","tr":"Yusuf’un gözünden","fa":"از نگاه یوسف"},"minSentences":2,"prompt":{"en":"You are Yusuf. You have just read the invitation letter. Write 2 sentences in first person: what worries you most, and who will you ask to come with you, and why?","tr":"Sen Yusuf’sun. Davet mektubunu az önce okudun. Birinci tekil şahısla 2 cümle yaz: seni en çok ne endişelendiriyor ve yanında kimin gelmesini isteyeceksin, neden?","fa":"تو یوسف هستی و همین حالا نامه‌ی دعوت را خوانده‌ای. از زبان خودت دو جمله بنویس: چه چیزی بیشتر از همه نگرانت می‌کند، و از چه کسی می‌خواهی همراهت بیاید و چرا؟"}},"exit":{"id":"c-hr-8-1-x","course":"hr","unit":"hr-8-1","type":"exit","items":[{"from":"hr-8-1","kind":"blank","point":2,"prompt":"The records ___ that the check was not done on 6 May.","options":["show","are show","showing"],"correct":0,"why":{"en":"show: 'the records' is plural, so the present simple without -s. 'Are show' mixes two forms, and 'showing' is not a full verb.","tr":"show: 'the records' çoğuldur, bu yüzden -s'siz geniş zaman. 'Are show' iki yapıyı karıştırır; 'showing' tam fiil değildir.","fa":"⁨show⁩ درست است، چون ⁨the records⁩ جمع است و حال ساده بدون ⁨-s⁩ می‌آید. ⁨are show⁩ دو ساختار را قاطی می‌کند و ⁨showing⁩ فعل کامل نیست."},"hint2":{"en":"records is plural, and this is a fact in the present. Which form goes with a plural subject?","tr":"records çoğul ve bu şimdiki zamanda bir olgu. Çoğul bir özneyle hangi biçim kullanılır?","fa":"⁨records⁩ جمع است و این یک واقعیت در زمان حال است. با فاعل جمع کدام شکل می‌آید؟"}},{"from":"hr-8-1","kind":"blank","point":2,"prompt":"It ___ that the log was signed before the check.","options":["appears","is appear","appearing"],"correct":0,"why":{"en":"appears: 'It appears that' states what the facts suggest, without judging. 'Is appear' mixes two forms, and 'appearing' is not a full verb.","tr":"appears: 'It appears that' bilgilerin neye işaret ettiğini yargılamadan söyler. 'Is appear' iki yapıyı karıştırır; 'appearing' tam fiil değildir.","fa":"appears درست است، چون It appears that بدون قضاوت می‌گوید شواهد چه نشان می‌دهند. is appear دو ساختار را قاطی می‌کند و appearing فعل کامل نیست."},"hint2":{"en":"It is singular, and the verb is in the present simple. Which form goes with it?","tr":"It tekil ve fiil geniş zamanda. it ile hangi biçim kullanılır?","fa":"⁨It⁩ مفرد است و فعل در زمان حال ساده است. با ⁨it⁩ کدام شکل می‌آید؟"}},{"from":"hr-8-1","kind":"mcq","point":4,"prompt":"Which step comes first in a fair disciplinary process?","options":["An investigation of the facts","A written warning","The appeal"],"correct":0,"why":{"en":"An investigation of the facts comes first, so the decision is made last. A warning or an appeal before the facts would be unfair.","tr":"Önce olgular araştırılır; böylece karar en son verilir. Olgulardan önce uyarı ya da itiraz adil olmaz.","fa":"اول بررسی واقعیت‌ها، تا تصمیم در آخر گرفته شود. اخطار یا اعتراض پیش از روشن شدن واقعیت‌ها منصفانه نیست."},"hint2":{"en":"A fair process has a fixed order, and the decision comes last. What has to happen before anyone is invited to a meeting?","tr":"Adil bir sürecin sabit bir sırası vardır ve karar en sona kalır. Biri toplantıya çağrılmadan önce ne olmalı?","fa":"یک روند منصفانه ترتیب ثابتی دارد و تصمیم آخر از همه می‌آید. قبل از اینکه کسی به جلسه دعوت شود، چه کاری باید انجام شود؟"}},{"from":"hr-7-4","kind":"blank","prompt":"___ our call on Monday, I am writing to confirm your start date.","options":["Following","Following to","After of"],"correct":0,"point":2,"why":{"en":"Following: 'Following our call' means after it, in formal letters. 'Following to' and 'After of' add a wrong preposition.","tr":"Following: resmî yazılarda 'Following our call' görüşmemizden sonra demektir. 'Following to' ve 'After of' yanlış bir edat ekler.","fa":"Following درست است، چون در نامه‌ی رسمی Following our call یعنی بعد از تماس‌مان. following to و after of حرف اضافه‌ی غلط دارند."},"hint2":{"en":"The gap opens with the event, and a noun follows (our call). Which formal word works on its own before a noun?","tr":"Boşluk olayla açılıyor ve ardından bir isim geliyor (our call). Hangi resmî kelime bir isimden önce tek başına kullanılır?","fa":"جای خالی با رویداد شروع می‌شود و بعدش یک اسم آمده (⁨our call⁩). کدام کلمه‌ی رسمی به‌تنهایی قبل از اسم می‌آید؟"}},{"from":"hr-7-2","kind":"blank","prompt":"He asked ___ he could have a copy of the notes.","options":["whether","that","what"],"correct":0,"point":2,"why":{"en":"whether: a reported yes/no question uses whether (or if). 'That' reports a statement, and 'what' needs a missing thing.","tr":"whether: aktarılan evet/hayır sorusu whether (ya da if) kullanır. 'That' bir bildirimi aktarır; 'what' eksik bir şey ister.","fa":"whether درست است، چون برای نقل سؤال بله‌یا‌نه whether یا if می‌آید. that جمله‌ی خبری را نقل می‌کند و what دنبال چیزی است که جمله ندارد."},"hint2":{"en":"The original was a yes/no question (Can I have a copy?). Which word reports a yes/no question?","tr":"Asıl soru bir evet/hayır sorusuydu (Can I have a copy?). Evet/hayır sorusu hangi kelimeyle aktarılır?","fa":"سؤال اصلی بله/نه بود (⁨Can I have a copy?).⁩ سؤال بله/نه با کدام کلمه نقل می‌شود؟"}},{"from":"hr-5-2","kind":"blank","prompt":"Last Tuesday the van ___ left unlocked.","options":["is","was","has"],"correct":1,"point":2,"why":{"en":"was: a finished event last Tuesday, and the van received the action: was + past participle. 'Is' is the present, and 'has left' doesn't fit last Tuesday.","tr":"was: geçen salı bitmiş bir olay ve minibüs eylemi aldı: was + üçüncü hâl. 'Is' şimdiki zamandır; 'has left' last Tuesday ile uymaz.","fa":"was درست است، چون اتفاق سه‌شنبه‌ی گذشته تمام شده و ون باز گذاشته شده: was و اسم مفعول. is زمان حال است و has با last Tuesday جور نیست."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
